/**
 * Go emitter for the SDK generator (Issue #1287).
 *
 * Emits:
 *   packages/go-client/operations.go - Operations table & typed service methods
 *   packages/go-client/models.go     - Go struct models with JSON tags
 */
import type { JsonSchema, NormalizedOperation, OpenApiDocument } from '../../src/lib/openapi/normalize';
import type { Emitter } from './emitters';

const HEADER = `// AUTO-GENERATED by \`npm run sdk:generate\` from the OpenAPI spec served at
// /api/v1/openapi.json. DO NOT EDIT: CI regenerates this file and fails on drift.

package soroban
`;

const GO_KEYWORDS = new Set([
  'break', 'case', 'chan', 'const', 'continue', 'default', 'defer', 'else',
  'fallthrough', 'for', 'func', 'go', 'goto', 'if', 'import', 'interface',
  'map', 'package', 'range', 'return', 'select', 'struct', 'switch', 'type',
  'var',
]);

const ACRONYMS: Record<string, string> = {
  id: 'ID',
  url: 'URL',
  uri: 'URI',
  http: 'HTTP',
  https: 'HTTPS',
  rpc: 'RPC',
  ws: 'WS',
  api: 'API',
  json: 'JSON',
  xdr: 'XDR',
  ip: 'IP',
  ttl: 'TTL',
  abi: 'ABI',
  sdk: 'SDK',
};

export function toPascalCase(name: string): string {
  if (!name) return 'Field';
  const parts = name.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  if (parts.length === 0) return 'Field';
  const pascal = parts
    .map((part) => {
      const lower = part.toLowerCase();
      if (ACRONYMS[lower]) return ACRONYMS[lower];
      return part.charAt(0).toUpperCase() + part.slice(1);
    })
    .join('');
  if (/^[0-9]/.test(pascal)) {
    return `M_${pascal}`;
  }
  if (GO_KEYWORDS.has(pascal.toLowerCase())) {
    return `${pascal}Field`;
  }
  return pascal;
}

export function modelNameGo(raw: string): string {
  return toPascalCase(raw);
}

function goType(
  schema: JsonSchema | null | undefined,
  known: Set<string>,
  depth = 0,
): string {
  if (!schema || depth > 5) return 'any';
  if (typeof schema.$ref === 'string') {
    const m = /^#\/components\/schemas\/(.+)$/.exec(schema.$ref);
    return m && known.has(m[1]) ? `*${modelNameGo(m[1])}` : 'any';
  }
  if (schema.oneOf || schema.anyOf) {
    return 'any';
  }
  if (schema.allOf) {
    if (schema.allOf.length === 1) {
      return goType(schema.allOf[0], known, depth + 1);
    }
    return 'map[string]any';
  }
  const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;
  switch (type) {
    case 'string':
      return 'string';
    case 'integer':
      return 'int64';
    case 'number':
      return 'float64';
    case 'boolean':
      return 'bool';
    case 'array':
      return `[]${goType(schema.items, known, depth + 1)}`;
    case 'object':
      return 'map[string]any';
    default:
      return schema.properties ? 'map[string]any' : 'any';
  }
}

export function emitGoModels(doc: OpenApiDocument): string {
  const schemas = doc.components?.schemas ?? {};
  const known = new Set(Object.keys(schemas));
  const structBlocks: string[] = [];

  const sortedKeys = Object.keys(schemas).sort();

  for (const raw of sortedKeys) {
    const s = schemas[raw];
    const name = modelNameGo(raw);

    if (s.properties && Object.keys(s.properties).length > 0) {
      const propKeys = Object.keys(s.properties).sort();
      const fields: string[] = [];

      for (const p of propKeys) {
        const propSchema = s.properties[p];
        const fieldName = toPascalCase(p);
        const baseType = goType(propSchema, known, 1);
        const isRequired = Array.isArray(s.required) && s.required.includes(p);
        const isPointer =
          !isRequired &&
          (propSchema.nullable === true ||
            (!baseType.startsWith('*') &&
              !baseType.startsWith('[]') &&
              !baseType.startsWith('map[') &&
              baseType !== 'any'));
        const finalType = isPointer ? `*${baseType}` : baseType;
        const tag = isRequired ? `\`json:"${p}"\`` : `\`json:"${p},omitempty"\``;
        fields.push(`\t${fieldName} ${finalType} ${tag}`);
      }

      structBlocks.push(
        `// ${name} represents the schema for ${raw}\ntype ${name} struct {\n${fields.join('\n')}\n}`,
      );
    } else {
      const aliasType = goType({ ...s, nullable: false }, known);
      structBlocks.push(
        `// ${name} is an alias for ${aliasType}\ntype ${name} = ${aliasType}`,
      );
    }
  }

  return `${HEADER}
${structBlocks.join('\n\n')}
`;
}

export function emitGoOperations(
  doc: OpenApiDocument,
  ops: NormalizedOperation[],
  fingerprint: string,
): string {
  const sortedOps = [...ops].sort((a, b) => a.id.localeCompare(b.id));

  const opEntries = sortedOps.map((op) => {
    const pathParams = op.params
      .filter((p) => p.in === 'path')
      .map((p) => `\t\t\t"${p.name}",`);

    const queryParams = op.params
      .filter((p) => p.in === 'query')
      .map((p) => {
        const enums =
          p.enum && p.enum.length > 0
            ? `Enum: []string{${p.enum.map((e) => `"${e}"`).join(', ')}}, `
            : '';
        return `\t\t\t{Name: "${p.name}", Type: "${p.type}", Required: ${p.required}, ${enums}},`;
      });

    return `\t"${op.id}": {
\t\tID: "${op.id}",
\t\tMethod: "${op.method.toUpperCase()}",
\t\tPath: "${op.path}",
\t\tPathParams: []string{
${pathParams.join('\n')}
\t\t},
\t\tQueryParams: []QueryParamMeta{
${queryParams.join('\n')}
\t\t},
\t\tBody: "${op.body ? (op.body.required ? 'required' : 'optional') : 'none'}",
\t\tContentType: "${op.body?.contentType ?? 'application/json'}",
\t\tDeprecated: ${op.deprecated ? 'true' : 'false'},
\t\tSummary: ${JSON.stringify(op.summary ?? '')},
\t},`;
  });

  return `${HEADER}
// SpecMetadata carries version and generation fingerprint information.
const (
\tSpecVersion     = "${doc.info?.version ?? '0.0.0'}"
\tSpecFingerprint = "${fingerprint}"
\tOperationCount  = ${ops.length}
)

// QueryParamMeta describes an allowed query parameter for an operation.
type QueryParamMeta struct {
\tName     string   \`json:"name"\`
\tType     string   \`json:"type"\`
\tRequired bool     \`json:"required"\`
\tEnum     []string \`json:"enum,omitempty"\`
}

// OperationMeta stores metadata for an API operation.
type OperationMeta struct {
\tID          string           \`json:"id"\`
\tMethod      string           \`json:"method"\`
\tPath        string           \`json:"path"\`
\tPathParams  []string         \`json:"pathParams"\`
\tQueryParams []QueryParamMeta \`json:"queryParams"\`
\tBody        string           \`json:"body"\`
\tContentType string           \`json:"contentType"\`
\tDeprecated  bool             \`json:"deprecated"\`
\tSummary     string           \`json:"summary"\`
}

// Operations contains runtime metadata for every OpenAPI operation.
var Operations = map[string]OperationMeta{
${opEntries.join('\n')}
}
`;
}

export const goEmitter: Emitter = ({ doc, ops, fingerprint }) => {
  return [
    {
      path: 'packages/go-client/models.go',
      content: emitGoModels(doc),
    },
    {
      path: 'packages/go-client/operations.go',
      content: emitGoOperations(doc, ops, fingerprint),
    },
  ];
};
